  let res = await callCustomAi({
    messages: [
      { role: "system", content: sysPrompt },
      { role: "user", content: userPrompt }
    ],
    maxTokens: 500,
    temperature: 0.7,
    jsonMode: false
  });

  if (!res.ok) {
    return { ok: false, code: res.code || "AI_ERROR", message: res.message };
  }

